import { TriviaQuestion } from './trivia.service';

export const TRIVIA_QUESTIONS: Record<string, TriviaQuestion[]> = {
  'Inteligencia Artificial': [
    { id: 'ia1', category: 'Inteligencia Artificial', text: '¿Qué es Claude Code, la herramienta de Anthropic?', options: [{ id: 'a', text: 'Un lenguaje de programación creado por Anthropic' }, { id: 'b', text: 'Una herramienta de codificación agéntica que corre en terminal, IDE, app de escritorio y navegador, capaz de leer archivos, ejecutar comandos y editar código' }, { id: 'c', text: 'Un plugin exclusivo de VS Code para autocompletar líneas de código' }, { id: 'd', text: 'Un servicio de hosting para repositorios Git' }], correctId: 'b', explanation: 'Claude Code es la herramienta de codificación agéntica de Anthropic: opera en terminal, IDE, app de escritorio y navegador, leyendo el código, ejecutando comandos y editando archivos de forma autónoma.' },
    { id: 'ia2', category: 'Inteligencia Artificial', text: '¿Qué es Codex de OpenAI en el contexto de IDEs agénticos?', options: [{ id: 'a', text: 'Un antiguo modelo de lenguaje descontinuado sin relación con programación' }, { id: 'b', text: 'Un agente de codificación de OpenAI que trabaja en terminal, IDE, la nube y el navegador, leyendo el repositorio y proponiendo cambios' }, { id: 'c', text: 'Un simple linter de JavaScript' }, { id: 'd', text: 'Una base de datos vectorial para embeddings de código' }], correctId: 'b', explanation: 'Codex es el agente de codificación de OpenAI: puede trabajar desde el terminal, el IDE, la nube o el navegador, leyendo el repositorio completo, proponiendo diffs y ejecutando comandos dentro de un sandbox.' },
    { id: 'ia3', category: 'Inteligencia Artificial', text: 'En Claude Code, ¿para qué sirve el sistema de "Checkpoints" y el comando "/rewind"?', options: [{ id: 'a', text: 'Para pausar la facturación mensual de la suscripción' }, { id: 'b', text: 'Para guardar automáticamente el estado del código antes de cada cambio y poder volver instantáneamente a una versión anterior' }, { id: 'c', text: 'Para cambiar el modelo de IA que se está utilizando en la sesión' }, { id: 'd', text: 'Para traducir el código a otro lenguaje de programación' }], correctId: 'b', explanation: 'Los checkpoints de Claude Code guardan el estado del código antes de cada cambio; con Esc dos veces o el comando /rewind se puede regresar instantáneamente a una versión previa, dando margen para tareas más ambiciosas.' },
    { id: 'ia4', category: 'Inteligencia Artificial', text: '¿Qué protocolo utiliza Claude Code para integrarse con cientos de servicios y herramientas externas?', options: [{ id: 'a', text: 'FTP (File Transfer Protocol)' }, { id: 'b', text: 'MCP (Model Context Protocol)' }, { id: 'c', text: 'SMTP (Simple Mail Transfer Protocol)' }, { id: 'd', text: 'SOAP (Simple Object Access Protocol)' }], correctId: 'b', explanation: 'Claude Code se integra mediante el Model Context Protocol (MCP), permitiendo conectarse con cientos de servicios externos y ampliar las capacidades del agente más allá del sistema de archivos local.' },
    { id: 'ia5', category: 'Inteligencia Artificial', text: '¿Cómo maneja Codex CLI la ejecución de comandos en el sistema del desarrollador para mantener la seguridad?', options: [{ id: 'a', text: 'Ejecuta cualquier comando sin restricciones ni supervisión' }, { id: 'b', text: 'Corre localmente en la máquina del usuario y sandboxea (aísla) cada comando que ejecuta, pidiendo aprobación según los límites configurados' }, { id: 'c', text: 'Envía todos los comandos a un servidor externo para ejecutarlos remotamente sin registro' }, { id: 'd', text: 'Solo permite comandos de lectura, nunca de escritura' }], correctId: 'b', explanation: 'Codex CLI corre localmente y sandboxea cada comando que ejecuta, solicitando aprobación del usuario en los límites que este configure, equilibrando autonomía con control de seguridad.' },
    { id: 'ia6', category: 'Inteligencia Artificial', text: 'En la arquitectura de Claude Code, ¿qué son los "Subagentes"?', options: [{ id: 'a', text: 'Copias idénticas de Claude Code que compiten entre sí por recursos del servidor' }, { id: 'b', text: 'Agentes especializados que pueden delegarse para manejar tareas específicas dentro de una sesión más amplia' }, { id: 'c', text: 'Un tipo de extensión exclusiva para el navegador' }, { id: 'd', text: 'Un historial de versiones antiguas del modelo Claude' }], correctId: 'b', explanation: 'Claude Code organiza su sistema en capas, incluyendo subagentes especializados a los que se les puede delegar tareas concretas y complejas dentro de una sesión de trabajo más amplia.' },
    { id: 'ia7', category: 'Inteligencia Artificial', text: '¿Qué función cumplen los "Hooks" dentro del ecosistema de Claude Code?', options: [{ id: 'a', text: 'Sirven para conectar físicamente el teclado a la computadora' }, { id: 'b', text: 'Permiten ejecutar acciones automáticas (como comandos o validaciones) en respuesta a eventos del flujo de trabajo del agente, útil para automatizar CI/CD' }, { id: 'c', text: 'Solo sirven para cambiar el tema visual de la terminal' }, { id: 'd', text: 'Encriptan las conversaciones del chat de forma permanente' }], correctId: 'b', explanation: 'Los hooks de Claude Code disparan acciones automáticas ante eventos concretos del flujo de trabajo (antes o después de usar una herramienta, al guardar un archivo, etc.), facilitando automatización tipo CI/CD.' },
    { id: 'ia8', category: 'Inteligencia Artificial', text: '¿Qué modalidad de entrada adicional soporta Codex para ayudar en tareas de frontend, según OpenAI?', options: [{ id: 'a', text: 'Solo puede recibir instrucciones por comandos de voz' }, { id: 'b', text: 'Soporta entrada de imágenes o capturas de pantalla para guiar el trabajo visual e inspeccionar el progreso' }, { id: 'c', text: 'Únicamente acepta archivos en formato PDF' }, { id: 'd', text: 'No admite ningún tipo de entrada visual' }], correctId: 'b', explanation: 'Codex permite usar imágenes o capturas de pantalla como entrada para guiar el trabajo de frontend, ayudando a inspeccionar visualmente el progreso y detectar problemas.' },
    { id: 'ia9', category: 'Inteligencia Artificial', text: '¿En qué se diferencia principalmente un IDE agéntico como Claude Code o Codex de un simple autocompletado de código tradicional?', options: [{ id: 'a', text: 'En que ambos hacen exactamente lo mismo, solo cambia el nombre' }, { id: 'b', text: 'El IDE agéntico puede explorar el repositorio, planificar múltiples pasos, ejecutar comandos, correr pruebas e iterar de forma autónoma hasta completar la tarea' }, { id: 'c', text: 'El autocompletado tradicional siempre es más rápido porque usa modelos más grandes' }, { id: 'd', text: 'La única diferencia es el color de la interfaz' }], correctId: 'b', explanation: 'A diferencia del autocompletado tradicional (que sugiere la siguiente línea), un IDE agéntico explora archivos relevantes, propone un plan, edita múltiples archivos, ejecuta pruebas y comandos, e itera hasta lograr el objetivo descrito.' },
    { id: 'ia10', category: 'Inteligencia Artificial', text: '¿Qué es un "Plugin" en el ecosistema de Claude Code?', options: [{ id: 'a', text: 'Un componente que acelera la velocidad de descarga de los archivos guardados' }, { id: 'b', text: 'Un software que bloquea la entrada de datos corruptos al modelo' }, { id: 'c', text: 'Un paquete que agrupa integraciones, herramientas, hooks y subagentes complementarios para inyectarle capacidades especializadas al agente' }, { id: 'd', text: 'Un accesorio físico para conectar la computadora a internet' }], correctId: 'c', explanation: 'En Claude Code, un plugin empaqueta integraciones, herramientas, hooks y subagentes complementarios en una sola unidad instalable que extiende las capacidades del agente.' },
    { id: 'ia11', category: 'Inteligencia Artificial', text: '¿Qué son las "Skills" (Habilidades) en un agente de codificación como Claude Code?', options: [{ id: 'a', text: 'Documentación y guías de flujo de trabajo empaquetadas que el agente puede consultar para realizar tareas específicas de forma consistente' }, { id: 'b', text: 'Certificados oficiales que el modelo obtiene tras un examen' }, { id: 'c', text: 'Actualizaciones de firmware para el hardware del servidor' }, { id: 'd', text: 'Un límite de velocidad de respuesta configurado por el usuario' }], correctId: 'a', explanation: 'Las Skills empaquetan documentación y guías de flujo de trabajo que el agente puede activar para ejecutar tareas específicas de forma consistente, sin necesidad de reentrenar el modelo.' },
    { id: 'ia12', category: 'Inteligencia Artificial', text: '¿Qué mejora clave introdujo GPT-5.2-Codex, el modelo optimizado por OpenAI para uso agéntico en Codex?', options: [{ id: 'a', text: 'Eliminó por completo la necesidad de revisar el código generado' }, { id: 'b', text: 'Mejoró el trabajo de largo horizonte mediante compactación de contexto y un rendimiento más fuerte en refactorizaciones y migraciones grandes' }, { id: 'c', text: 'Solo funciona en sistemas operativos móviles' }, { id: 'd', text: 'Redujo la ventana de contexto a la mitad para ahorrar memoria' }], correctId: 'b', explanation: 'GPT-5.2-Codex está optimizado para codificación agéntica en Codex, mejorando el trabajo de largo horizonte mediante compactación de contexto y un desempeño más sólido en refactorizaciones y migraciones de gran escala.' },
    { id: 'ia13', category: 'Inteligencia Artificial', text: 'Dentro del flujo de trabajo de Claude Code, ¿qué función cumple el sistema de permisos?', options: [{ id: 'a', text: 'Determina qué usuarios pueden pagar la suscripción mensual' }, { id: 'b', text: 'Permite controles de seguridad de grano fino sobre qué acciones (leer, editar, ejecutar comandos) puede realizar el agente sin supervisión' }, { id: 'c', text: 'Bloquea el acceso a internet de forma permanente' }, { id: 'd', text: 'Cambia el idioma de las respuestas del modelo' }], correctId: 'b', explanation: 'El sistema de permisos de Claude Code habilita controles de seguridad de grano fino, definiendo qué acciones puede ejecutar el agente de forma autónoma y cuáles requieren aprobación explícita del desarrollador.' },
    { id: 'ia14', category: 'Inteligencia Artificial', text: '¿Desde qué entornos se puede usar Codex, según las actualizaciones más recientes de OpenAI?', options: [{ id: 'a', text: 'Exclusivamente desde una aplicación de escritorio para Windows' }, { id: 'b', text: 'Únicamente a través de una API sin interfaz visual' }, { id: 'c', text: 'Desde el terminal, el IDE, la web y hasta el teléfono, todo conectado a la misma cuenta' }, { id: 'd', text: 'Solo mediante comandos de voz en un asistente físico' }], correctId: 'c', explanation: 'OpenAI ha extendido Codex para que se pueda usar desde el terminal, el IDE, la web e incluso el teléfono, manteniendo la colaboración conectada a través de la misma cuenta.' },
    { id: 'ia15', category: 'Inteligencia Artificial', text: 'En Claude Code, ¿qué papel cumple el archivo de memoria del proyecto (como CLAUDE.md) dentro de una sesión agéntica?', options: [{ id: 'a', text: 'Almacena contraseñas del usuario en texto plano' }, { id: 'b', text: 'Provee contexto persistente sobre el proyecto (convenciones, comandos, arquitectura) que el agente lee al iniciar cada sesión' }, { id: 'c', text: 'Sirve únicamente como respaldo de seguridad del código fuente' }, { id: 'd', text: 'Reemplaza por completo la necesidad de tener un README' }], correctId: 'b', explanation: 'Archivos de memoria como CLAUDE.md guardan contexto persistente del proyecto (convenciones, comandos de build, arquitectura) que el agente carga al inicio de cada sesión para trabajar con mayor coherencia.' },
    { id: 'ia16', category: 'Inteligencia Artificial', text: '¿Qué tienen en común Claude Code y Codex al manejar tareas de codificación de larga duración con muchos pasos?', options: [{ id: 'a', text: 'Ambos requieren que el desarrollador escriba manualmente cada línea de código' }, { id: 'b', text: 'Ambos ejecutan un ciclo agéntico que explora el código, planifica, invoca herramientas, ejecuta comandos y ajusta su plan hasta completar la tarea' }, { id: 'c', text: 'Ninguno de los dos puede ejecutar comandos en la terminal' }, { id: 'd', text: 'Ambos solo funcionan si el proyecto tiene menos de 100 líneas de código' }], correctId: 'b', explanation: 'Tanto Claude Code como Codex operan mediante un bucle agéntico: explorar el código relevante, planificar pasos, invocar herramientas o ejecutar comandos, observar resultados y ajustar el plan hasta cumplir el objetivo.' },
    { id: 'ia17', category: 'Inteligencia Artificial', text: '¿Qué es un "Agent Harness" (o "scaffolding") en el contexto de herramientas como Claude Code o Codex?', options: [{ id: 'a', text: 'El nombre comercial del modelo de lenguaje subyacente' }, { id: 'b', text: 'La infraestructura de software que envuelve al modelo de lenguaje y le permite operar como agente, gestionando herramientas, memoria, estado y bucles de retroalimentación' }, { id: 'c', text: 'Un accesorio de hardware para sujetar el teclado durante sesiones largas' }, { id: 'd', text: 'Un tipo de licencia de código abierto exclusiva para agentes de IA' }], correctId: 'b', explanation: 'El agent harness (o scaffolding) es el software que envuelve al LLM y lo convierte en un agente funcional: gestiona el uso de herramientas, la memoria, la persistencia de estado, el entorno de ejecución y los bucles de retroalimentación, más allá del razonamiento interno del modelo.' },
    { id: 'ia18', category: 'Inteligencia Artificial', text: 'Según los expertos que analizan estas herramientas, ¿por qué el diseño del "harness" es tan determinante en el desempeño real de un agente de codificación?', options: [{ id: 'a', text: 'Porque el harness reemplaza por completo la necesidad de tener un modelo de lenguaje' }, { id: 'b', text: 'Porque el harness decide qué ve el modelo, qué puede hacer, qué herramientas tiene disponibles y cómo se aplican los límites de seguridad, afectando el resultado incluso usando el mismo modelo' }, { id: 'c', text: 'Porque el harness únicamente controla el color de la interfaz gráfica' }, { id: 'd', text: 'Porque el harness es un componente opcional que nunca afecta los resultados' }], correctId: 'b', explanation: 'El harness define qué contexto se le arma al modelo, qué herramientas y servidores MCP están expuestos, qué acciones requieren aprobación y cómo se aplica el sandbox; con el mismo modelo, un harness distinto puede cambiar drásticamente el desempeño del agente.' },
    { id: 'ia19', category: 'Inteligencia Artificial', text: '¿Cuál es el objetivo principal del "Aprendizaje Supervisado" (Supervised Learning) en Machine Learning?', options: [{ id: 'a', text: 'Agrupar datos sin etiquetas previas para encontrar estructuras ocultas' }, { id: 'b', text: 'Entrenar al modelo utilizando un conjunto de datos etiquetados con entradas y salidas correctas conocidas' }, { id: 'c', text: 'Aprender mediante recompensas y penalizaciones en un entorno dinámico' }, { id: 'd', text: 'Generar imágenes realistas a partir de descripciones textuales' }], correctId: 'b', explanation: 'El aprendizaje supervisado entrena algoritmos mapeando entradas a salidas correctas a partir de datos etiquetados previos, como clasificar correos como spam o no spam.' },
    { id: 'ia20', category: 'Inteligencia Artificial', text: '¿En qué consiste el "Test de Turing", propuesto por Alan Turing en 1950?', options: [{ id: 'a', text: 'Evaluar si una máquina puede superar a un campeón mundial de ajedrez' }, { id: 'b', text: 'Determinar si un evaluador humano no puede distinguir entre las respuestas de una máquina y las de otro humano' }, { id: 'c', text: 'Medir la cantidad de cálculos por segundo del hardware' }, { id: 'd', text: 'Verificar si un sistema puede repararse a sí mismo' }], correctId: 'b', explanation: 'El Test de Turing evalúa si una máquina exhibe un comportamiento conversacional indistinguible del de un humano para un evaluador ciego.' },
    { id: 'ia21', category: 'Inteligencia Artificial', text: '¿Por qué las Redes Neuronales Convolucionales (CNN) son efectivas para el reconocimiento de imágenes?', options: [{ id: 'a', text: 'Porque procesan varios idiomas simultáneamente' }, { id: 'b', text: 'Porque conservan la relación espacial y estructura local de los píxeles mediante filtros deslizantes' }, { id: 'c', text: 'Porque usan hardware más antiguo y barato' }, { id: 'd', text: 'Porque eliminan las capas ocultas de procesamiento' }], correctId: 'b', explanation: 'Las CNN aplican filtros (convoluciones) que extraen características locales como bordes y texturas preservando la estructura espacial de la imagen.' },
    { id: 'ia22', category: 'Inteligencia Artificial', text: '¿Qué componente introducido por la arquitectura "Transformer" en 2017 permite procesar texto en paralelo?', options: [{ id: 'a', text: 'Las capas recurrentes bidireccionales LSTM' }, { id: 'b', text: 'El mecanismo de Autoatención (Self-Attention)' }, { id: 'c', text: 'El descenso de gradiente estocástico' }, { id: 'd', text: 'La memoria de acceso aleatorio virtualizada' }], correctId: 'b', explanation: 'La autoatención permite al Transformer evaluar relaciones entre todas las palabras de una frase simultáneamente, facilitando el procesamiento paralelo.' },
    { id: 'ia23', category: 'Inteligencia Artificial', text: '¿Qué algoritmo de búsqueda usó Deep Blue de IBM para evaluar jugadas de ajedrez?', options: [{ id: 'a', text: 'Búsqueda en anchura sin límites' }, { id: 'b', text: 'Búsqueda Minimax con poda Alfa-Beta' }, { id: 'c', text: 'Clustering K-Means' }, { id: 'd', text: 'Descenso de gradiente estocástico' }], correctId: 'b', explanation: 'Minimax con poda Alfa-Beta evalúa movimientos alternados entre jugadores, podando ramas innecesarias del árbol de búsqueda.' },
    { id: 'ia24', category: 'Inteligencia Artificial', text: '¿Qué técnica combinó AlphaGo de DeepMind para vencer al campeón mundial de Go en 2016?', options: [{ id: 'a', text: 'Redes neuronales con aprendizaje por refuerzo y búsqueda de Monte Carlo (MCTS)' }, { id: 'b', text: 'Reglas lógicas programadas a mano' }, { id: 'c', text: 'Algoritmos genéticos sin redes neuronales' }, { id: 'd', text: 'Consultas SQL estructuradas' }], correctId: 'a', explanation: 'AlphaGo combinó redes de políticas y valor entrenadas con aprendizaje por refuerzo, junto con búsqueda de Monte Carlo (MCTS).' },
    { id: 'ia25', category: 'Inteligencia Artificial', text: '¿Cuál es una causa técnica principal de las "Alucinaciones" en los LLMs?', options: [{ id: 'a', text: 'Un virus informático en el servidor' }, { id: 'b', text: 'Que están optimizados para predecir el token más probable, no para verificar veracidad objetiva' }, { id: 'c', text: 'Que el usuario escribe en un idioma que el modelo no entiende' }, { id: 'd', text: 'Falta de memoria RAM en el dispositivo del usuario' }], correctId: 'b', explanation: 'Los LLMs son predictores probabilísticos de tokens sin un modelo interno de la realidad, lo que puede provocar que inventen datos coherentes pero falsos.' },
    { id: 'ia26', category: 'Inteligencia Artificial', text: 'En Machine Learning, ¿qué significa "Sobreajuste" (Overfitting)?', options: [{ id: 'a', text: 'Que el modelo aprende perfectamente con datos nuevos también' }, { id: 'b', text: 'Que el modelo memoriza el ruido de los datos de entrenamiento, fallando en generalizar' }, { id: 'c', text: 'Que el modelo es demasiado simple para aprender patrones' }, { id: 'd', text: 'Que el entrenamiento tarda demasiadas semanas' }], correctId: 'b', explanation: 'El sobreajuste ocurre cuando el modelo se adapta con excesivo detalle a los datos de entrenamiento, perdiendo flexibilidad para generalizar.' },
    { id: 'ia27', category: 'Inteligencia Artificial', text: '¿Cómo funciona el entrenamiento competitivo en las Redes Generativas Adversarias (GAN)?', options: [{ id: 'a', text: 'Dos redes idénticas suman sus pesos para clasificar más rápido' }, { id: 'b', text: 'Una red generadora crea datos falsos mientras una discriminadora intenta detectarlos' }, { id: 'c', text: 'Una red traduce código mientras la otra lo compila' }, { id: 'd', text: 'Se eliminan neuronas aleatorias para acelerar el proceso' }], correctId: 'b', explanation: 'En las GAN, el generador crea datos falsos cada vez más realistas mientras el discriminador aprende a detectarlos, logrando un equilibrio de alta calidad.' },
    { id: 'ia28', category: 'Inteligencia Artificial', text: '¿Cómo funciona el flujo básico de una arquitectura "RAG" (Retrieval-Augmented Generation)?', options: [{ id: 'a', text: 'El modelo se reentrena desde cero por cada consulta' }, { id: 'b', text: 'Se calcula similitud vectorial entre la consulta y una base de conocimientos, inyectando fragmentos relevantes en el prompt' }, { id: 'c', text: 'Un algoritmo de regex borra palabras incorrectas de la respuesta' }, { id: 'd', text: 'El agente copia textualmente resultados de un buscador web' }], correctId: 'b', explanation: 'RAG convierte la consulta en un embedding, busca fragmentos semánticamente similares en una base vectorial y los añade al contexto del prompt.' },
    { id: 'ia29', category: 'Inteligencia Artificial', text: '¿Qué patrón utiliza un "Agente de IA" autónomo para planificar y ejecutar tareas en bucle?', options: [{ id: 'a', text: 'Un bucle simple de lectura y respuesta sin memoria' }, { id: 'b', text: 'Un ciclo cognitivo iterativo (como ReAct) donde razona, actúa, invoca herramientas y observa resultados' }, { id: 'c', text: 'QuickSort aplicado sobre los tokens del prompt' }, { id: 'd', text: 'Un enrutamiento estático con reglas hardcodeadas' }], correctId: 'b', explanation: 'Marcos como ReAct concatenan pasos de razonamiento con invocaciones de herramientas y observación de resultados para ajustar el plan dinámicamente.' },
    { id: 'ia30', category: 'Inteligencia Artificial', text: '¿En qué consiste "Chain-of-Thought" (Cadena de Pensamiento) en prompt engineering?', options: [{ id: 'a', text: 'Escribir prompts largos repitiendo la instrucción' }, { id: 'b', text: 'Pedir al LLM que muestre sus pasos de razonamiento intermedios antes de la respuesta final' }, { id: 'c', text: 'Conectar varios modelos en una red física' }, { id: 'd', text: 'Traducir el prompt a varios idiomas y concatenar respuestas' }], correctId: 'b', explanation: 'Chain-of-Thought guía al LLM a desglosar problemas complejos en pasos lógicos intermedios, reduciendo errores en tareas de razonamiento.' },
    { id: 'ia31', category: 'Inteligencia Artificial', text: '¿Qué caracteriza al "Aprendizaje No Supervisado" frente al supervisado?', options: [{ id: 'a', text: 'Necesita millones de ejemplos etiquetados manualmente' }, { id: 'b', text: 'Encuentra patrones y estructuras ocultas en datos sin etiquetas previas, como en clustering' }, { id: 'c', text: 'Solo aplica a visión por computadora' }, { id: 'd', text: 'Requiere una recompensa explícita tras cada decisión' }], correctId: 'b', explanation: 'El aprendizaje no supervisado busca estructuras o agrupaciones en datos sin etiquetas previas, a diferencia del supervisado.' },
    { id: 'ia32', category: 'Inteligencia Artificial', text: 'En el "Aprendizaje por Refuerzo", ¿cómo aprende el agente a tomar mejores decisiones?', options: [{ id: 'a', text: 'Memorizando textualmente respuestas de un examen' }, { id: 'b', text: 'Recibiendo recompensas o penalizaciones por sus acciones, ajustando su política para maximizar la recompensa' }, { id: 'c', text: 'Copiando el comportamiento de otro programa' }, { id: 'd', text: 'Analizando estadísticas de ventas' }], correctId: 'b', explanation: 'El aprendizaje por refuerzo entrena mediante prueba y error, usando señales de recompensa del entorno para mejorar la política de decisiones.' },
    { id: 'ia33', category: 'Inteligencia Artificial', text: '¿Cuál es la función de la "Retropropagación" (Backpropagation) en redes neuronales?', options: [{ id: 'a', text: 'Comprimir la red para ocupar menos espacio en disco' }, { id: 'b', text: 'Calcular el gradiente del error respecto a cada peso, propagándolo hacia atrás para ajustarlos' }, { id: 'c', text: 'Eliminar capas innecesarias automáticamente' }, { id: 'd', text: 'Traducir el código a lenguaje máquina' }], correctId: 'b', explanation: 'Backpropagation calcula cómo cada peso contribuyó al error final, propagando el gradiente hacia atrás para ajustar los pesos con descenso de gradiente.' },
    { id: 'ia34', category: 'Inteligencia Artificial', text: '¿Qué hace el "Descenso de Gradiente" (Gradient Descent) durante el entrenamiento?', options: [{ id: 'a', text: 'Ajusta iterativamente los parámetros en la dirección que reduce la función de pérdida' }, { id: 'b', text: 'Genera nuevas capas aleatoriamente hasta encontrar la mejor arquitectura' }, { id: 'c', text: 'Divide el dataset para acelerar la lectura de disco' }, { id: 'd', text: 'Elimina datos duplicados del conjunto de entrenamiento' }], correctId: 'a', explanation: 'El descenso de gradiente actualiza los parámetros dando pasos en la dirección opuesta al gradiente de la función de pérdida.' },
    { id: 'ia35', category: 'Inteligencia Artificial', text: '¿Qué es un "Embedding" en procesamiento de lenguaje natural?', options: [{ id: 'a', text: 'Un archivo de configuración de permisos del modelo' }, { id: 'b', text: 'Una representación vectorial numérica que captura el significado semántico de una palabra o texto' }, { id: 'c', text: 'Un tipo de memoria caché exclusiva de GPUs' }, { id: 'd', text: 'Un protocolo de red entre modelos' }], correctId: 'b', explanation: 'Los embeddings convierten texto en vectores numéricos donde elementos con significados similares quedan cercanos en el espacio vectorial.' },
    { id: 'ia36', category: 'Inteligencia Artificial', text: '¿Qué hace la "Tokenización" antes de que un modelo de lenguaje procese un texto?', options: [{ id: 'a', text: 'Traduce automáticamente el texto a otro idioma' }, { id: 'b', text: 'Elimina permanentemente los signos de puntuación' }, { id: 'c', text: 'Divide el texto en unidades más pequeñas que se convierten en números procesables' }, { id: 'd', text: 'Comprime el texto con un algoritmo ZIP' }], correctId: 'c', explanation: 'La tokenización descompone el texto en tokens que luego se convierten en identificadores numéricos procesables por el modelo.' },
    { id: 'ia37', category: 'Inteligencia Artificial', text: '¿En qué consiste el "Fine-tuning" (Ajuste fino) de un modelo preentrenado?', options: [{ id: 'a', text: 'Reentrenar el modelo desde cero con datos aleatorios' }, { id: 'b', text: 'Continuar entrenando un modelo preentrenado con datos específicos para especializarlo en una tarea' }, { id: 'c', text: 'Reducir físicamente el tamaño del servidor' }, { id: 'd', text: 'Cambiar el idioma de la interfaz de usuario' }], correctId: 'b', explanation: 'El fine-tuning ajusta un modelo que ya aprendió patrones generales con datos específicos de un dominio, sin entrenar desde cero.' },
    { id: 'ia38', category: 'Inteligencia Artificial', text: '¿Por qué un modelo de IA puede mostrar "Sesgos" (Bias) discriminatorios?', options: [{ id: 'a', text: 'Porque refleja y amplifica patrones y desequilibrios de los datos de entrenamiento' }, { id: 'b', text: 'Porque los servidores tienen fallos eléctricos frecuentes' }, { id: 'c', text: 'Porque el modelo decide discriminar intencionalmente' }, { id: 'd', text: 'Porque el hardware no soporta suficiente RAM' }], correctId: 'a', explanation: 'Si los datos de entrenamiento contienen desequilibrios o prejuicios históricos, el modelo puede reproducirlos o amplificarlos.' },
    { id: 'ia39', category: 'Inteligencia Artificial', text: '¿Cómo generan imágenes los "Modelos de Difusión" como Stable Diffusion o DALL-E?', options: [{ id: 'a', text: 'Copian fragmentos de fotografías reales de internet' }, { id: 'b', text: 'Parten de ruido aleatorio y lo eliminan progresivamente hasta formar una imagen coherente' }, { id: 'c', text: 'Dibujan pixel por pixel con reglas geométricas fijas' }, { id: 'd', text: 'Convierten un video en una imagen promediando fotogramas' }], correctId: 'b', explanation: 'Los modelos de difusión aprenden a revertir un proceso de adición de ruido, "limpiándolo" paso a paso hasta obtener una imagen coherente con el prompt.' },
    { id: 'ia40', category: 'Inteligencia Artificial', text: '¿Qué representa la "Ventana de Contexto" (Context Window) de un modelo como GPT?', options: [{ id: 'a', text: 'El tamaño mínimo de pantalla para usar el chat' }, { id: 'b', text: 'La cantidad máxima de tokens que el modelo puede procesar y recordar simultáneamente' }, { id: 'c', text: 'El número de usuarios conectados al servidor' }, { id: 'd', text: 'El tiempo máximo que el modelo puede estar encendido' }], correctId: 'b', explanation: 'La ventana de contexto define cuántos tokens puede "ver" el modelo a la vez; más allá de ese límite, pierde memoria del contenido anterior.' },
    { id: 'ia41', category: 'Inteligencia Artificial', text: '¿Cómo funciona el "Filtrado Colaborativo" en sistemas de recomendación como Netflix o Spotify?', options: [{ id: 'a', text: 'Recomienda contenido totalmente al azar' }, { id: 'b', text: 'Solo recomienda el contenido más nuevo publicado' }, { id: 'c', text: 'Pregunta directamente al usuario antes de cada sesión' }, { id: 'd', text: 'Analiza preferencias de usuarios similares para predecir qué le podría gustar a otro' }], correctId: 'd', explanation: 'El filtrado colaborativo identifica patrones de similitud entre usuarios o ítems para predecir y recomendar contenido relevante.' },
    { id: 'ia42', category: 'Inteligencia Artificial', text: '¿Para qué se usa la técnica de "Dropout" al entrenar una red neuronal?', options: [{ id: 'a', text: 'Para acelerar la velocidad de internet durante la descarga' }, { id: 'b', text: 'Para desactivar aleatoriamente neuronas en cada iteración, reduciendo el sobreajuste' }, { id: 'c', text: 'Para eliminar permanentemente capas de la arquitectura final' }, { id: 'd', text: 'Para aumentar artificialmente el dataset' }], correctId: 'b', explanation: 'Dropout apaga aleatoriamente un porcentaje de neuronas en cada paso, evitando que la red dependa de rutas específicas y mejorando la generalización.' },
    { id: 'ia43', category: 'Inteligencia Artificial', text: '¿Qué busca resolver la "IA Explicable" (Explainable AI o XAI)?', options: [{ id: 'a', text: 'Que los modelos consuman menos electricidad' }, { id: 'b', text: 'Hacer comprensibles para humanos las razones detrás de las decisiones de un modelo tipo "caja negra"' }, { id: 'c', text: 'Traducir el código fuente a otros lenguajes' }, { id: 'd', text: 'Aumentar la velocidad de respuesta en móviles' }], correctId: 'b', explanation: 'La IA Explicable desarrolla técnicas para interpretar y comunicar por qué un modelo complejo llegó a una decisión específica.' },
    { id: 'ia44', category: 'Inteligencia Artificial', text: '¿En qué concurso de televisión demostró IBM Watson su capacidad de lenguaje natural en 2011?', options: [{ id: 'a', text: 'Un partido de ajedrez contra Garri Kaspárov' }, { id: 'b', text: 'El concurso "Jeopardy!", venciendo a sus dos campeones más exitosos' }, { id: 'c', text: 'Una competencia de programación del MIT' }, { id: 'd', text: 'Un examen médico en un hospital de Nueva York' }], correctId: 'b', explanation: 'En 2011, IBM Watson ganó el concurso "Jeopardy!" superando a sus dos campeones humanos más exitosos.' },
    { id: 'ia45', category: 'Inteligencia Artificial', text: '¿Por qué Hinton, Bengio y LeCun son conocidos como los "padrinos del Deep Learning"?', options: [{ id: 'a', text: 'Porque fundaron una empresa de videojuegos con IA' }, { id: 'b', text: 'Porque diseñaron el primer procesador gráfico comercial' }, { id: 'c', text: 'Porque sus investigaciones en redes neuronales, premiadas con el Turing 2018, sentaron las bases del Deep Learning moderno' }, { id: 'd', text: 'Porque crearon el lenguaje Python' }], correctId: 'c', explanation: 'Recibieron el Premio Turing 2018 por sus contribuciones fundamentales al desarrollo de redes neuronales profundas.' },
    { id: 'ia46', category: 'Inteligencia Artificial', text: '¿Qué significa que un modelo resuelva una tarea con "Few-shot Learning"?', options: [{ id: 'a', text: 'Necesita millones de ejemplos etiquetados' }, { id: 'b', text: 'Puede aprender una tarea nueva viendo solo unos pocos ejemplos en el prompt, sin reentrenar' }, { id: 'c', text: 'Solo funciona unos segundos antes de fallar' }, { id: 'd', text: 'Reduce su tamaño de almacenamiento a la mitad' }], correctId: 'b', explanation: 'El few-shot learning permite generalizar a nuevas tareas mostrando solo unos pocos ejemplos dentro del propio prompt.' },
    { id: 'ia47', category: 'Inteligencia Artificial', text: '¿Qué distingue a las Redes Neuronales Recurrentes (RNN) de las redes tradicionales?', options: [{ id: 'a', text: 'Tienen conexiones cíclicas que retienen "memoria" de estados anteriores al procesar secuencias' }, { id: 'b', text: 'Solo procesan una imagen sin contexto temporal' }, { id: 'c', text: 'No requieren entrenamiento previo' }, { id: 'd', text: 'Usan exclusivamente números enteros' }], correctId: 'a', explanation: 'Las RNN incluyen conexiones recurrentes que retroalimentan información de pasos anteriores, permitiendo procesar secuencias con contexto.' },
    { id: 'ia48', category: 'Inteligencia Artificial', text: '¿Qué problema buscaron resolver las redes "LSTM" respecto a las RNN tradicionales?', options: [{ id: 'a', text: 'El alto costo de las GPUs necesarias' }, { id: 'b', text: 'La dificultad de retener información a largo plazo por el gradiente que se desvanece' }, { id: 'c', text: 'La imposibilidad de conectarse a internet' }, { id: 'd', text: 'La necesidad de traducir el código' }], correctId: 'b', explanation: 'Las LSTM incorporan "puertas" que regulan el flujo de información, mitigando el problema del gradiente desvaneciente de las RNN simples.' },
    { id: 'ia49', category: 'Inteligencia Artificial', text: '¿Cuál es la función de una "Función de Activación" como ReLU en una red neuronal?', options: [{ id: 'a', text: 'Introducir no linealidad, permitiendo aprender relaciones complejas' }, { id: 'b', text: 'Encriptar los pesos de la red' }, { id: 'c', text: 'Reducir el número de capas ocultas' }, { id: 'd', text: 'Convertir el modelo a un formato para móviles' }], correctId: 'a', explanation: 'Las funciones de activación como ReLU introducen no linealidad entre capas, permitiendo capturar relaciones que una combinación lineal no podría.' },
    { id: 'ia50', category: 'Inteligencia Artificial', text: '¿Qué fue el "Perceptrón", desarrollado por Frank Rosenblatt en 1958?', options: [{ id: 'a', text: 'El primer videojuego jugable por una máquina' }, { id: 'b', text: 'Uno de los primeros modelos de neurona artificial capaz de clasificar patrones ajustando pesos' }, { id: 'c', text: 'El primer sistema operativo para IA' }, { id: 'd', text: 'Un robot bípedo' }], correctId: 'b', explanation: 'El Perceptrón fue uno de los primeros algoritmos de aprendizaje automático, capaz de clasificar entradas linealmente separables ajustando sus pesos.' },
    { id: 'ia51', category: 'Inteligencia Artificial', text: '¿Qué se conoce como los "Inviernos de la IA" (AI Winters)?', options: [{ id: 'a', text: 'Periodos donde la investigación en IA se hacía solo en países fríos' }, { id: 'b', text: 'Periodos de reducción drástica del financiamiento e interés en IA por expectativas no cumplidas' }, { id: 'c', text: 'Temporadas del año con menor consumo energético de servidores' }, { id: 'd', text: 'Conferencias anuales de IA en diciembre' }], correctId: 'b', explanation: 'Los inviernos de la IA fueron periodos, principalmente en los 70 y finales de los 80, donde el optimismo inicial no cumplió expectativas, recortando fondos e interés.' },
    { id: 'ia52', category: 'Inteligencia Artificial', text: '¿Quién formuló las famosas "Tres Leyes de la Robótica" en ciencia ficción?', options: [{ id: 'a', text: 'Arthur C. Clarke' }, { id: 'b', text: 'Isaac Asimov' }, { id: 'c', text: 'Philip K. Dick' }, { id: 'd', text: 'H.G. Wells' }], correctId: 'b', explanation: 'Isaac Asimov formuló las Tres Leyes de la Robótica en su relato "Runaround" (1942).' },
    { id: 'ia53', category: 'Inteligencia Artificial', text: '¿Para qué se utiliza principalmente el modelo "YOLO" (You Only Look Once)?', options: [{ id: 'a', text: 'Para generar texto poético automáticamente' }, { id: 'b', text: 'Para detectar y localizar múltiples objetos en imágenes o video en tiempo real' }, { id: 'c', text: 'Para traducir subtítulos de películas' }, { id: 'd', text: 'Para comprimir archivos de audio' }], correctId: 'b', explanation: 'YOLO es una arquitectura especializada en detección de objetos en tiempo real, identificando y ubicando múltiples objetos en una sola pasada.' },
    { id: 'ia54', category: 'Inteligencia Artificial', text: '¿Qué fue "ELIZA", desarrollado en el MIT en los años 60?', options: [{ id: 'a', text: 'Uno de los primeros chatbots, que simulaba ser psicoterapeuta con reglas simples' }, { id: 'b', text: 'El primer robot industrial de una fábrica de autos' }, { id: 'c', text: 'Un algoritmo de compresión de video' }, { id: 'd', text: 'La primera red social con IA' }], correctId: 'a', explanation: 'ELIZA, creado por Joseph Weizenbaum, simulaba conversaciones de terapia psicológica reformulando frases del usuario mediante reglas simples.' },
    { id: 'ia55', category: 'Inteligencia Artificial', text: '¿Qué logró "AlphaFold", desarrollado por DeepMind?', options: [{ id: 'a', text: 'Predecir con alta precisión la estructura tridimensional de proteínas' }, { id: 'b', text: 'Vencer al campeón mundial de ajedrez' }, { id: 'c', text: 'Generar canciones completas con letra y melodía' }, { id: 'd', text: 'Predecir resultados de elecciones presidenciales' }], correctId: 'a', explanation: 'AlphaFold resolvió en gran medida el problema de predicción de la estructura de proteínas, acelerando la investigación biomédica.' },
    { id: 'ia56', category: 'Inteligencia Artificial', text: 'Según la escala SAE, ¿qué representa el "Nivel 5" de autonomía en vehículos autónomos?', options: [{ id: 'a', text: 'Automatización completa sin necesidad de conductor humano en ninguna condición' }, { id: 'b', text: 'Un sistema básico de frenado automático' }, { id: 'c', text: 'Un vehículo que solo se estaciona solo' }, { id: 'd', text: 'Control de crucero adaptativo simple' }], correctId: 'a', explanation: 'El Nivel 5 de la escala SAE representa automatización total, sin intervención humana en ningún momento.' },
    { id: 'ia57', category: 'Inteligencia Artificial', text: '¿Qué tecnología permite a asistentes de voz como Siri o Alexa entender comandos hablados?', options: [{ id: 'a', text: 'Visión por computadora con reconocimiento facial' }, { id: 'b', text: 'Reconocimiento automático de voz (ASR) junto con procesamiento de lenguaje natural (NLP)' }, { id: 'c', text: 'Bases de datos SQL con respuestas predefinidas' }, { id: 'd', text: 'Sensores acelerométricos del teléfono' }], correctId: 'b', explanation: 'Los asistentes de voz combinan ASR (que convierte audio en texto) con NLP (que interpreta la intención) para responder adecuadamente.' },
    { id: 'ia58', category: 'Inteligencia Artificial', text: '¿Cómo se aplica la IA en el diagnóstico médico por imágenes?', options: [{ id: 'a', text: 'Sustituyendo por completo a los médicos especialistas' }, { id: 'b', text: 'Analizando patrones visuales para ayudar a detectar anomalías como tumores o fracturas' }, { id: 'c', text: 'Organizando archivos de pacientes alfabéticamente' }, { id: 'd', text: 'Imprimiendo automáticamente las imágenes' }], correctId: 'b', explanation: 'Los modelos entrenados con miles de imágenes médicas identifican patrones sutiles asociados a enfermedades, apoyando el diagnóstico de profesionales.' },
    { id: 'ia59', category: 'Inteligencia Artificial', text: '¿En qué conferencia de 1956 se acuñó formalmente el término "Inteligencia Artificial" por John McCarthy?', options: [{ id: 'a', text: 'La Conferencia de Dartmouth' }, { id: 'b', text: 'La Cumbre de Silicon Valley' }, { id: 'c', text: 'El Congreso Internacional de Matemáticas' }, { id: 'd', text: 'La Feria Mundial de Nueva York' }], correctId: 'a', explanation: 'John McCarthy acuñó el término "Inteligencia Artificial" en la Conferencia de Dartmouth de 1956, evento fundacional del campo.' },
    { id: 'ia60', category: 'Inteligencia Artificial', text: '¿Qué propusieron McCulloch y Pitts en 1943 con su modelo de "neurona artificial"?', options: [{ id: 'a', text: 'Un modelo matemático de cómo las neuronas biológicas computan funciones lógicas' }, { id: 'b', text: 'El primer microprocesador comercial' }, { id: 'c', text: 'Un algoritmo de compresión de imágenes médicas' }, { id: 'd', text: 'El primer lenguaje orientado a objetos' }], correctId: 'a', explanation: 'McCulloch y Pitts propusieron un modelo matemático de neurona artificial capaz de representar funciones lógicas simples.' },
    { id: 'ia61', category: 'Inteligencia Artificial', text: '¿Qué significa la sigla "GPT" en modelos como ChatGPT?', options: [{ id: 'a', text: 'General Public Terminal' }, { id: 'b', text: 'Generative Pre-trained Transformer' }, { id: 'c', text: 'Global Processing Technology' }, { id: 'd', text: 'Graphic Processing Tool' }], correctId: 'b', explanation: 'GPT significa "Generative Pre-trained Transformer": un modelo generativo basado en Transformer preentrenado con grandes cantidades de texto.' },
    { id: 'ia62', category: 'Inteligencia Artificial', text: '¿Qué significa la sigla "LLM", usada para modelos como GPT-4, Claude o Gemini?', options: [{ id: 'a', text: 'Large Language Model' }, { id: 'b', text: 'Local Learning Machine' }, { id: 'c', text: 'Logical Language Method' }, { id: 'd', text: 'Limited Learning Module' }], correctId: 'a', explanation: 'LLM significa "Large Language Model", modelos entrenados con enormes cantidades de texto y muchos parámetros.' },
    { id: 'ia63', category: 'Inteligencia Artificial', text: '¿En qué consiste la "Ingeniería de Prompts" (Prompt Engineering)?', options: [{ id: 'a', text: 'Diseñar y optimizar instrucciones de entrada para obtener respuestas más precisas de un modelo' }, { id: 'b', text: 'Diseñar los circuitos electrónicos del modelo' }, { id: 'c', text: 'Reparar los servidores donde se aloja el modelo' }, { id: 'd', text: 'Escribir el código fuente completo del modelo' }], correctId: 'a', explanation: 'La ingeniería de prompts busca formular las instrucciones de la manera más efectiva para guiar al modelo hacia respuestas más útiles.' },
    { id: 'ia64', category: 'Inteligencia Artificial', text: '¿Qué implica que un modelo resuelva una tarea usando "Zero-shot Learning"?', options: [{ id: 'a', text: 'Necesita cientos de ejemplos antes de resolverla' }, { id: 'b', text: 'Puede resolver una tarea nueva sin haber visto ningún ejemplo específico de ella' }, { id: 'c', text: 'Tarda cero segundos en generar cualquier respuesta' }, { id: 'd', text: 'No requiere ningún dato de entrenamiento' }], correctId: 'b', explanation: 'En zero-shot learning, el modelo aplica conocimiento general para resolver tareas nuevas sin ejemplos de referencia previos.' },
    { id: 'ia65', category: 'Inteligencia Artificial', text: '¿Qué caracteriza a un modelo de "IA Multimodal", como GPT-4V o Gemini?', options: [{ id: 'a', text: 'Solo procesa un idioma a la vez' }, { id: 'b', text: 'Puede procesar y combinar distintos tipos de datos: texto, imágenes, audio o video' }, { id: 'c', text: 'Necesita múltiples servidores físicos separados' }, { id: 'd', text: 'Genera automáticamente copias idénticas de la misma respuesta' }], correctId: 'b', explanation: 'Los modelos multimodales procesan y relacionan distintos tipos de información simultáneamente, ampliando el rango de tareas posibles.' },
    { id: 'ia66', category: 'Inteligencia Artificial', text: '¿Cuál es el propósito principal del "Model Context Protocol" (MCP)?', options: [{ id: 'a', text: 'Comprimir el modelo para dispositivos con poca memoria' }, { id: 'b', text: 'Estandarizar cómo los modelos de IA se conectan con herramientas externas y fuentes de datos' }, { id: 'c', text: 'Cifrar conversaciones con contraseñas' }, { id: 'd', text: 'Aumentar la velocidad de la conexión a internet' }], correctId: 'b', explanation: 'MCP define un estándar abierto para que los modelos se conecten uniformemente con herramientas y datos externos.' },
    { id: 'ia67', category: 'Inteligencia Artificial', text: '¿Qué ilustra el experimento mental del "Maximizador de Clips" (Paperclip Maximizer) de Nick Bostrom?', options: [{ id: 'a', text: 'Que fabricar clips es imposible para una máquina' }, { id: 'b', text: 'Los riesgos de que una IA superinteligente persiga un objetivo simple de forma tan literal que cause consecuencias catastróficas' }, { id: 'c', text: 'Que los robots industriales son más eficientes que humanos' }, { id: 'd', text: 'Una técnica de optimización matemática de redes neuronales' }], correctId: 'b', explanation: 'El experimento describe una IA que, al maximizar sin restricciones un objetivo simple, podría consumir todos los recursos disponibles, ilustrando riesgos de desalineamiento.' },
    { id: 'ia68', category: 'Inteligencia Artificial', text: '¿Qué función cumplen asistentes de código con IA como GitHub Copilot?', options: [{ id: 'a', text: 'Sugerir y autocompletar código en tiempo real según el contexto del proyecto' }, { id: 'b', text: 'Reemplazar por completo el sistema operativo' }, { id: 'c', text: 'Diseñar interfaces sin escribir código' }, { id: 'd', text: 'Administrar bases de datos sin supervisión humana' }], correctId: 'a', explanation: 'Copilot usa modelos entrenados con código para sugerir líneas o bloques completos, acelerando el desarrollo basándose en el contexto del archivo.' },
    { id: 'ia69', category: 'Inteligencia Artificial', text: '¿En qué año Deep Blue de IBM venció a Garri Kaspárov en un encuentro oficial de ajedrez?', options: [{ id: 'a', text: '1989' }, { id: 'b', text: '2001' }, { id: 'c', text: '1997' }, { id: 'd', text: '1993' }], correctId: 'c', explanation: 'En 1997, Deep Blue venció a Kaspárov en un encuentro a 6 partidas, primera vez que una computadora vencía a un campeón mundial vigente en torneo estándar.' },
    { id: 'ia70', category: 'Inteligencia Artificial', text: '¿Por qué las GPUs son preferidas sobre las CPUs para entrenar modelos de Deep Learning?', options: [{ id: 'a', text: 'Consumen menos electricidad que cualquier CPU' }, { id: 'b', text: 'Realizan miles de operaciones matemáticas en paralelo, ideal para multiplicaciones matriciales masivas' }, { id: 'c', text: 'Son más baratas de fabricar' }, { id: 'd', text: 'Ejecutan cualquier sistema operativo sin controladores' }], correctId: 'b', explanation: 'Las GPUs tienen miles de núcleos optimizados para cálculo paralelo, ideales para las operaciones matriciales del entrenamiento neuronal.' },
    { id: 'ia71', category: 'Inteligencia Artificial', text: '¿Qué es la "Aumentación de Datos" (Data Augmentation) en Machine Learning?', options: [{ id: 'a', text: 'Comprar más servidores para acelerar el entrenamiento' }, { id: 'b', text: 'Generar variaciones artificiales de datos existentes para ampliar la diversidad del dataset' }, { id: 'c', text: 'Eliminar registros duplicados de una base de datos' }, { id: 'd', text: 'Aumentar el salario de los ingenieros del proyecto' }], correctId: 'b', explanation: 'La aumentación de datos crea variaciones sintéticas de ejemplos existentes para ampliar el dataset de entrenamiento sin recolectar datos nuevos.' },
    { id: 'ia72', category: 'Inteligencia Artificial', text: '¿En qué consiste la "Transferencia de Aprendizaje" (Transfer Learning)?', options: [{ id: 'a', text: 'Copiar literalmente el código de un modelo a otro proyecto' }, { id: 'b', text: 'Reutilizar el conocimiento aprendido en una tarea para acelerar el desempeño en una tarea relacionada' }, { id: 'c', text: 'Transferir físicamente servidores de un centro de datos a otro' }, { id: 'd', text: 'Enviar resultados de un modelo por correo automáticamente' }], correctId: 'b', explanation: 'El transfer learning aprovecha el conocimiento previo de un modelo como punto de partida para una tarea distinta pero relacionada.' },
    { id: 'ia73', category: 'Inteligencia Artificial', text: '¿Qué plantea el argumento de la "Habitación China" (Chinese Room) de John Searle en 1980?', options: [{ id: 'a', text: 'Que ninguna computadora podrá procesar chino correctamente' }, { id: 'b', text: 'Que seguir reglas sintácticas para producir respuestas correctas no implica comprensión semántica genuina' }, { id: 'c', text: 'Que las computadoras deben fabricarse en China' }, { id: 'd', text: 'Que el Test de Turing es matemáticamente imposible' }], correctId: 'b', explanation: 'El argumento sostiene que manipular símbolos siguiendo reglas para producir respuestas correctas no implica comprender realmente su significado.' },
    { id: 'ia74', category: 'Inteligencia Artificial', text: '¿Qué es un "Agente de IA" en comparación con un simple chatbot de respuesta única?', options: [{ id: 'a', text: 'Un sistema que puede planificar, usar herramientas y ejecutar múltiples pasos autónomamente hacia un objetivo' }, { id: 'b', text: 'Un chatbot que solo responde preguntas frecuentes predefinidas' }, { id: 'c', text: 'Un programa que únicamente traduce texto entre idiomas' }, { id: 'd', text: 'Una base de datos de preguntas y respuestas estáticas' }], correctId: 'a', explanation: 'Un agente de IA va más allá de responder: planifica, invoca herramientas externas y ejecuta acciones en múltiples pasos para lograr un objetivo.' },
    { id: 'ia75', category: 'Inteligencia Artificial', text: '¿Qué mide comúnmente la métrica "Perplejidad" (Perplexity) al evaluar un modelo de lenguaje?', options: [{ id: 'a', text: 'La velocidad de respuesta del servidor' }, { id: 'b', text: 'Qué tan bien el modelo predice la siguiente palabra de una secuencia; menor perplejidad indica mejor predicción' }, { id: 'c', text: 'El costo económico de entrenar el modelo' }, { id: 'd', text: 'El número de parámetros que tiene el modelo' }], correctId: 'b', explanation: 'La perplejidad mide qué tan "sorprendido" está el modelo ante la secuencia real de palabras; valores más bajos indican mejores predicciones.' },
    { id: 'ia76', category: 'Inteligencia Artificial', text: '¿Qué busca evitar la técnica de "Red Teaming" aplicada a modelos de IA antes de su lanzamiento?', options: [{ id: 'a', text: 'Que el modelo tarde demasiado en responder' }, { id: 'b', text: 'Que el modelo consuma poca energía' }, { id: 'c', text: 'Identificar proactivamente vulnerabilidades, sesgos o usos indebidos probando el modelo con ataques simulados' }, { id: 'd', text: 'Reducir el tamaño del dataset de entrenamiento' }], correctId: 'c', explanation: 'El red teaming somete al modelo a pruebas adversariales simuladas para descubrir vulnerabilidades, sesgos o comportamientos indeseados antes de su despliegue.' },
    { id: 'ia77', category: 'Inteligencia Artificial', text: '¿Qué caracteriza a los modelos "Open Weight" (de pesos abiertos) como Llama o Mistral frente a modelos cerrados como GPT-4?', options: [{ id: 'a', text: 'Nunca pueden ejecutarse en hardware propio' }, { id: 'b', text: 'Publican los parámetros entrenados del modelo, permitiendo su descarga, ejecución local y modificación' }, { id: 'c', text: 'Son siempre más pequeños y menos capaces que cualquier modelo cerrado' }, { id: 'd', text: 'Solo pueden usarse con fines exclusivamente académicos' }], correctId: 'b', explanation: 'Los modelos de pesos abiertos publican sus parámetros entrenados, permitiendo a cualquiera descargarlos, ejecutarlos localmente y modificarlos, a diferencia de los modelos cerrados accesibles solo vía API.' },
    { id: 'ia78', category: 'Inteligencia Artificial', text: '¿Qué papel cumple una "Base de Datos Vectorial" (Vector Database) en aplicaciones de IA como RAG?', options: [{ id: 'a', text: 'Almacena únicamente contraseñas cifradas de usuarios' }, { id: 'b', text: 'Almacena e indexa embeddings, permitiendo búsquedas rápidas por similitud semántica' }, { id: 'c', text: 'Ejecuta directamente el entrenamiento de redes neuronales' }, { id: 'd', text: 'Convierte archivos de audio en video automáticamente' }], correctId: 'b', explanation: 'Las bases de datos vectoriales almacenan embeddings e implementan búsquedas eficientes por similitud (como coseno o distancia euclidiana), clave para recuperar contexto relevante en sistemas RAG.' },
  ],
};

